style.css:
@-moz-document domain("youtube.com") {
/* Alterar a logo do YouTube */
    #logo-icon-container, #logo {
        background-image: url("https://i.imgur.com/KaK26yk.png") !important;
        background-repeat: no-repeat !important;
        background-size: contain !important;
        width: 120px !important; /* Tamanho da logo ajustado */
        height: 38px !important; /* Altura da logo ajustada */
    }

    /* Remover logo padrão */
    #logo-icon-container svg, #logo svg {
        display: none !important; /* Remove a logo padrão */
    }
}
